import{_ as d,C as s,o as n,c as o,j as e,a as r,E as i,a1 as l}from"./chunks/framework.CqITaWnH.js";const y=JSON.parse('{"title":"Eval Iterations v1–v8","description":"","frontmatter":{},"headers":[],"relativePath":"en/eval.md","filePath":"en/eval.md"}'),h={name:"en/eval.md"};function c(u,t,m,g,p,b){const a=s("EvalChart");return n(),o("div",null,[t[0]||(t[0]=e("h1",{id:"eval-iterations-v1–v8",tabindex:"-1"},[r("Eval Iterations v1–v8 "),e("a",{class:"header-anchor",href:"#eval-iterations-v1–v8","aria-label":'Permalink to "Eval Iterations v1–v8"'},"​")],-1)),t[1]||(t[1]=e("p",null,[r("No tuning by vibes: an automated harness over 45 real queries ("),e("strong",null,"LLM-as-judge"),r(" grades every query × top-5 result), every change gets scored — winners stay, losers roll back.")],-1)),i(a),t[2]||(t[2]=l('<h2 id="glossary" tabindex="-1">Glossary <a class="header-anchor" href="#glossary" aria-label="Permalink to &quot;Glossary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Metric</th><th>Plainly</th><th>What 1.0 means</th></tr></thead><tbody><tr><td><strong>nDCG@5</strong></td><td>ranking quality of the top 5 — position matters, not just presence</td><td>the most relevant exactly on top</td></tr><tr><td><strong>MRR</strong></td><td>where the first relevant result lands on average (reciprocal)</td><td>rank #1 relevant for every query</td></tr><tr><td><strong>P@5</strong></td><td>share of relevant films in the top 5 — order-agnostic hit rate</td><td>all five relevant</td></tr></tbody></table><h2 id="version-overview" tabindex="-1">Version overview <a class="header-anchor" href="#version-overview" aria-label="Permalink to &quot;Version overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Version</th><th>Change</th><th>nDCG@5</th><th>MRR</th><th>P@5</th><th>Verdict</th></tr></thead><tbody><tr><td>v1</td><td>baseline (hybrid + RRF)</td><td>0.9307</td><td>0.925</td><td>0.86</td><td>starting point</td></tr><tr><td>v2</td><td>several gating ideas at once</td><td>0.9255</td><td>0.9167</td><td>0.84</td><td>regression — changed too much</td></tr><tr><td><strong>v3</strong></td><td>keep only the parser alias</td><td><strong>0.9512</strong></td><td>0.925</td><td><strong>0.89</strong></td><td>first big win</td></tr><tr><td>v4</td><td>+ English-domain reranker</td><td>0.9368</td><td>0.925</td><td>0.73</td><td>wrong model, precision dropped</td></tr><tr><td>v5</td><td>step-back always on</td><td>0.9350</td><td>0.925</td><td>0.85</td><td>helped vague, hurt specific</td></tr><tr><td><strong>v6</strong></td><td>step-back gated conditionally</td><td>0.9623</td><td><strong>1.000</strong></td><td>0.84</td><td>perfect MRR ⭐</td></tr><tr><td>v7</td><td>English-domain reranker, retried</td><td>0.9368</td><td>0.9417</td><td>0.79</td><td>confirmed: it&#39;s the model</td></tr><tr><td><strong>v8</strong></td><td>Chinese-domain reranker (bce)</td><td><strong>0.9625</strong></td><td>0.975</td><td><strong>0.89</strong></td><td>best balance ⭐</td></tr></tbody></table><h2 id="iteration-diary" tabindex="-1">Iteration diary <a class="header-anchor" href="#iteration-diary" aria-label="Permalink to &quot;Iteration diary&quot;">​</a></h2><details class="note"><summary>v1 — measure before touching anything</summary> Plant the yardstick: score the plain pipeline as-is — 0.9307. Optimization without a baseline is self-congratulation. </details><details class="note"><summary>v2 — greed: four ideas at once, regression</summary> Shipped four query-understanding improvements together. -0.005; three queries improved, five worsened, impossible to assign credit.<br><b class="turn">→ One variable per round, from then on.</b></details><details class="note"><summary>v3 — unbundle, keep one: first big win</summary> Kept only the keyword alias table. +0.02 → 0.9512; previously-missed signals all landed.<br><b class="turn">→ Extending the alias table is pure profit.</b></details><details class="note"><summary>v4 — first reranker: faceplant</summary> An English-domain reranker dropped nDCG and P@5 to 0.73.<br><b class="turn">→ &quot;More AI&quot; doesn&#39;t mean better; it can&#39;t read a Chinese library.</b></details><details class="note"><summary>v5 — query abstraction: helps vague, hurts specific</summary> Step-back vector helped vague queries, injected noise into specific ones. Net loss.<br><b class="turn">→ Double-edged — the question is when, not whether.</b></details><details class="note"><summary>v6 — same trick, plus a switch: perfect MRR ⭐</summary> Abstraction only when the parser finds nothing concrete. 0.9623, rank-1 correct on every query.<br><b class="turn">→ Gate the smallest possible knob.</b></details><details class="note"><summary>v7 — retry English reranker: confirmed it&#39;s the model</summary> Added context + position-aware blend — architecturally right, still 0.9368.<br><b class="turn">→ Architecture patches can&#39;t rescue the wrong model.</b></details><details class="note"><summary>v8 — Chinese-domain reranker: best balance ⭐</summary> Same API, Chinese-IR-trained bce. nDCG flat, P@5 +0.05, zero eval failures.<br><b class="turn">→ A reranker&#39;s language domain beats its architecture.</b></details><h2 id="appendix-a-thriftier-yardstick-—-the-judge-s-model-and-hardware" tabindex="-1">Appendix: a thriftier yardstick — the judge&#39;s model and hardware <a class="header-anchor" href="#appendix-a-thriftier-yardstick-—-the-judge-s-model-and-hardware" aria-label="Permalink to &quot;Appendix: a thriftier yardstick — the judge&#39;s model and hardware&quot;">​</a></h2><p>The grader was <strong>a local model throughout</strong>. Why not cloud? One round is 45 × top-5 = up to 225 gradings; eleven rounds approach 2,500 — free cloud tiers hit limits and fight the product for quota. Local judge: zero marginal cost, reruns anytime, reproducible.</p><p>v1–v8 used a larger MoE model (35B-A3B, GPU); later a smaller <strong>8B dense model on an NPU</strong> re-scored — <strong>a different judge is a different yardstick; not comparable with the table above</strong>:</p><table tabindex="0"><thead><tr><th>Round</th><th>Scope</th><th>nDCG@5</th><th>MRR</th><th>Verdict</th></tr></thead><tbody><tr><td>8B judge @ NPU (subset)</td><td>20 queries</td><td>0.9286</td><td>0.9417</td><td>small-model + NPU pipeline works</td></tr><tr><td>8B judge @ NPU (full)</td><td>45 queries</td><td>0.9233</td><td>0.9444</td><td>sustained, low-power, off the GPU</td></tr></tbody></table>',17))])}const f=d(h,[["render",c]]);export{y as __pageData,f as default};
